///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_saveReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf73010.tx_fn_save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_chkDup
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_chkDup = async function () {
    const sbmOptions = {
        id: "tx_fn_chkDup",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_chkDupReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf73010.tx_fn_chkDup" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.closeFrame
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.closeFrame = function () {
    /* sdd-asis-lifecycle:begin fn_closeFrame — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('ipt_dupChkYn').getValue() !== 'Y') {
        await $c.win.alert("단위조항 중복확인 후 저장이 가능합니다.");
        return;
    }
    var sprtRoomNo = $('#slc_junmoon option:selected').val();
    if (sprtRoomNo.length == 0) {
        await $c.win.alert("법규전문을 선택해 주시기 바랍니다.");
        return;
    }
    if (!await $c.win.confirm("저장하시겠습니까?")) {
        return;
    }
    var sprtRoomNo = $('#slc_junmoon option:selected').val();
    sprtRoomNo = sprtRoomNo.split("_")[0];
    $c.util.getComponent('ipt_sprtRoomNo').setValue(sprtRoomNo);
    $c.util.getComponent('ipt_relLawDtlContn').setValue(DEXT5.getBodyValue("dext5editor1"));
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeText
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeText = function () {
    /* sdd-asis-lifecycle:begin fn_changeText — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_dupChkYn').setValue("N");
    setBtnEnable($('#dupBtn'));
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_chkDup = scwin.tx_fn_chkDup;
